-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('team__parent__tree', ARRAY[to_regclass('"hd"."teams"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"hd"."teams"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."team__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

CREATE FUNCTION authz_gen."hd.users:column name:items"(p_row "hd"."users") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT CASE WHEN authz_int."hd.users:seen"("users"."id") THEN ARRAY[
    coalesce(((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false)), false),
    coalesce((SELECT authz_int.scope_cmd('hd.users', 'update')), false),
    coalesce(coalesce((active), false), false),
    coalesce(coalesce("users"."id" = (SELECT authz.uid()), false), false),
    coalesce(EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "users"."workspace_id"), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[5]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "users";
END;

CREATE FUNCTION authz_gen."hd.users:column name:why"(p_row "hd"."users") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."hd.users:column name:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update name : self or workspace.manage  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule hd.users update name'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on hd.users'; END IF;
  IF NOT v[3] THEN RETURN NEXT '  no   the row fails the user type''s where {active}'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'self';
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || 'workspace.manage';
  IF NOT v[5] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("users"."workspace_id")::text AS id FROM (SELECT (p_row).*) AS "users") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('workspace', v_t.id, 'manage') l LIMIT 20;
    END LOOP;
  END IF;
END $f$;

-- hd.users update name (line 128): self or workspace.manage
-- Whether the rule holds for a row: called by the trigger's WHEN, which is kept parsed, as a policy is, so the app
-- role uses it without naming it (authz_int)
CREATE FUNCTION authz_int."hd.users:column name:holds"(p_row "hd"."users") RETURNS boolean
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT coalesce(((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false)), false) FROM pg_catalog.unnest(ARRAY[p_row]) AS "users";
END;

-- refused: says why. The rule is checked in the trigger's WHEN below
CREATE FUNCTION authz_int."hd.users:column name"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_row "hd"."users";
BEGIN
  -- the row as the table's own: a partition's columns may be in another order, a table that inherits may have more
  IF TG_RELID = '"hd"."users"'::pg_catalog.regclass THEN v_row := OLD;
  ELSE v_row := pg_catalog.jsonb_populate_record(NULL::"hd"."users", pg_catalog.to_jsonb(OLD)); END IF;
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."hd.users:column name:why"(v_row) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION 'changing name of hd.users % needs: self or workspace.manage', OLD."id" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
    SCHEMA = 'hd', TABLE = 'users', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
END $f$;

-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update name" BEFORE UPDATE ON "hd"."users" FOR EACH ROW
  WHEN ((OLD."name" IS DISTINCT FROM NEW."name")
    AND pg_catalog.row_security_active('"hd"."users"'::pg_catalog.regclass)
    AND NOT authz_int."hd.users:column name:holds"(pg_catalog.jsonb_populate_record(NULL::"hd"."users", pg_catalog.to_jsonb(OLD))))
  EXECUTE FUNCTION authz_int."hd.users:column name"();

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('"hd_app"');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'hd_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'hd_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'hd_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- the policy's owner (or a member of it): its sessions are believed unsigned, it may read rowstile's tables
  -- (the session key among them) and turn row-level security off (applying refuses it, AZ624: this finds a grant made since)
  FOR r IN SELECT n.nspowner::regrole AS owner FROM pg_namespace n, pg_roles a
           WHERE n.nspname = 'authz_int' AND a.oid = v_role AND NOT a.rolsuper AND pg_has_role(v_role, n.nspowner, 'MEMBER') LOOP
    severity := 'error'; object := 'hd_app';
    problem := format('is the policy''s owner %s, or a member of it: who is signed in is believed without a signature, and it may read rowstile''s tables and turn row-level security off. The app role must be a role of its own: not the tables'' owner or the policy''s, nor a member of either', r.owner);
    RETURN NEXT;
  END LOOP;
  -- rowstile's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."customer_org__member"', 'authz_int."team__lead"', 'authz_int."team__manage"', 'authz_int."team__member"', 'authz_int."team__oversee"', 'authz_int."team__view"', 'authz_int."ticket__cc"', 'authz_int."ticket__reply"', 'authz_int."ticket__responder"', 'authz_int."ticket__roles:work"', 'authz_int."ticket__view"', 'authz_int."ticket__work"', 'authz_int."user__org_tickets"', 'authz_int."user__self"', 'authz_int."workspace__admin"', 'authz_int."workspace__agent"', 'authz_int."workspace__connected"', 'authz_int."workspace__manage"', 'authz_int."workspace__member"', 'authz_int."workspace__view"', 'authz_int."workspace__work"', 'authz_int."workspace__work_all"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"hd_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"hd_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"hd.comments:delete:items"', '"hd.comments:delete:why"', '"hd.comments:insert:items"', '"hd.comments:insert:refuse"', '"hd.comments:insert:why"', '"hd.comments:rules:explain"', '"hd.comments:update:items"', '"hd.comments:update:refuse"', '"hd.comments:update:why"', '"hd.customer_orgs:column id, workspace_id:items"', '"hd.customer_orgs:column id, workspace_id:why"', '"hd.customer_orgs:delete:items"', '"hd.customer_orgs:delete:why"', '"hd.customer_orgs:insert:items"', '"hd.customer_orgs:insert:refuse"', '"hd.customer_orgs:insert:why"', '"hd.customer_orgs:rules:explain"', '"hd.customer_orgs:update:items"', '"hd.customer_orgs:update:refuse"', '"hd.customer_orgs:update:why"', '"hd.integrations:column id, workspace_id:items"', '"hd.integrations:column id, workspace_id:why"', '"hd.integrations:delete:items"', '"hd.integrations:delete:why"', '"hd.integrations:insert:items"', '"hd.integrations:insert:refuse"', '"hd.integrations:insert:why"', '"hd.integrations:rules:explain"', '"hd.integrations:update:items"', '"hd.integrations:update:refuse"', '"hd.integrations:update:why"', '"hd.support_access:delete:items"', '"hd.support_access:delete:why"', '"hd.support_access:insert:items"', '"hd.support_access:insert:refuse"', '"hd.support_access:insert:why"', '"hd.support_access:rules:explain"', '"hd.support_access:update:items"', '"hd.support_access:update:refuse"', '"hd.support_access:update:why"', '"hd.team_leads:delete:items"', '"hd.team_leads:delete:why"', '"hd.team_leads:insert:items"', '"hd.team_leads:insert:refuse"', '"hd.team_leads:insert:why"', '"hd.team_leads:rules:explain"', '"hd.team_leads:update:items"', '"hd.team_leads:update:refuse"', '"hd.team_leads:update:why"', '"hd.team_members:delete:items"', '"hd.team_members:delete:why"', '"hd.team_members:insert:items"', '"hd.team_members:insert:refuse"', '"hd.team_members:insert:why"', '"hd.team_members:rules:explain"', '"hd.team_members:update:items"', 